from taf.ul.auto_commissioning.injector.taf_internal_locator import TAFManagedObjectLocator
from taf.ul.auto_commissioning.pydelta import PyDelta
from taf.ul.auto_commissioning.utils import change_mrbts_id_and_nrbts_id, change_mrbtsid, get_mrbts_id, get_nrbts_id


class Injector:

    def __init__(self, taf_int_scf):
        self.taf_int_scf = taf_int_scf
        self.taf_int_scf_mos = taf_int_scf.raml.cmData.get_all_descendant_mos()
        self.base_mrbts_id = self._get_mrbtsid()
        self.base_nrbts_id = self._get_nrbtsid()

        self.pydelta = None

    def inject_json_delta(self, delta_addr):
        self.pydelta = PyDelta.load_from_json(delta_addr)
        self._inject()

    def inject_pkl_delta(self, delta_addr):
        self.pydelta = PyDelta.load_from_pickle(delta_addr)
        self._inject()

    def _inject(self):
        self._prepare_scf_delta_to_inject()

        self._add()
        self._remove()
        self._replace()

    def _add(self):
        self._overwrite_managed_objects(
            self.pydelta.added, expect_object_to_be_present=False, warn_on_unexpected="already added, overwrite")

    def _remove(self):
        mo_locator = TAFManagedObjectLocator(
            self.taf_int_scf,
            expect_to_be_present=True,
            allow_unexpected=True,
            warn_on_unexpected="object is already removed, skip")

        [mo.remove() for mo in mo_locator.get_correlating_managed_objects(self.pydelta.removed)]

    def _replace(self):
        self._overwrite_managed_objects(
            self.pydelta.changed, expect_object_to_be_present=True, warn_on_unexpected="nothing to replace, adding")

    def _overwrite_managed_objects(self, managed_objects, expect_object_to_be_present=True, warn_on_unexpected=""):
        """
        When a superobject is readded then it is not localizable anymore
        (and so subobjects are not localizable as well)
        Thus implementation of this method must first locate all elements and only then overwrite them
        """

        mo_locator = TAFManagedObjectLocator(
            self.taf_int_scf,
            expect_object_to_be_present,
            allow_unexpected=True,
            warn_on_unexpected=warn_on_unexpected)

        for match in mo_locator.locate_and_match_managed_objects(managed_objects):
            if match["original"] is not None:
                match["original"].remove()
            self._append_mo_to_taf_int_scf(match["new"].translate_to_taf_object())

    def _append_mo_to_taf_int_scf(self, mo):
        self.taf_int_scf.raml.cmData.append(mo)

    def _prepare_scf_delta_to_inject(self):
        """Changes all MRBTS IDs and NRBTS Ids to the one that is in base scf. It changes it in distnames and params"""
        self._change_mrbts_id_and_nrbts_id(mo_objects=self.pydelta.added)
        self._change_mrbts_id_and_nrbts_id(mo_objects=self.pydelta.changed)

    def _change_mrbts_id_and_nrbts_id(self, mo_objects):
        for mo in mo_objects:
            if self.base_nrbts_id and self.base_mrbts_id:
                mo.dist_name = change_mrbts_id_and_nrbts_id(mo.dist_name, self.base_mrbts_id, self.base_nrbts_id)
                mo.change_mrbts_id_and_nrbts_id_in_link(self.base_mrbts_id, self.base_nrbts_id)
            elif self.base_mrbts_id:
                mo.dist_name = change_mrbtsid(mo.dist_name, self.base_mrbts_id)
                mo.change_mrbts_id_in_link(self.base_mrbts_id)

    def _get_mrbtsid(self):
        return get_mrbts_id(full_distname=self.taf_int_scf_mos[0].dist_name)

    def _get_nrbtsid(self):
        for mo in self.taf_int_scf_mos:
            if self._is_nrbtsid_in_distname(mo.dist_name):
                return get_nrbts_id(full_distname=mo.dist_name)
        else:
            return None

    def _is_nrbtsid_in_distname(self, distname):
        return bool("NRBTS-" in distname)
